RELS=list(EXPECTED)
def sha(p:Path)->str: return hashlib.sha256(p.read_bytes()).hexdigest().upper()
def fail(msg:str): raise RuntimeError(msg)
def main():
 root=Path(sys.argv[1] if len(sys.argv)>1 else Path(__file__).resolve().parents[1]).resolve()
 paths={r:root/r for r in RELS}
 missing=[r for r,p in paths.items() if not p.is_file()]
 if missing: fail('missing required files: '+', '.join(missing))
 actual={r:sha(p) for r,p in paths.items()}
 if all(actual[r]==OUTPUT_EXPECTED[r] for r in RELS):
  m=json.loads(paths['manifest.json'].read_text('utf-8-sig'))
  if m.get('version')!=NEW_MANIFEST_VERSION or m.get('version_name')!=NEW_VERSION: fail('already-applied hashes but manifest version mismatch')
  print('APPLY_FIX331023_ALREADY_OK'); return
 bad=[r for r in RELS if actual[r]!=EXPECTED[r]]
 if bad: fail('input hash mismatch: '+', '.join(f"{r}={actual[r]} expected={EXPECTED[r]}" for r in bad))
 m=json.loads(paths['manifest.json'].read_text('utf-8-sig'))
 if m.get('version')!=OLD_MANIFEST_VERSION or m.get('version_name')!=OLD_VERSION: fail('input manifest version mismatch')
 staged={}; backups={r:paths[r].read_bytes() for r in RELS}; tmp=Path(tempfile.mkdtemp(prefix='.fix331023-',dir=str(root)))
 try:
  for r in RELS:
   data=zlib.decompress(base64.b85decode(PAYLOADS[r].encode('ascii'))); q=tmp/r; q.parent.mkdir(parents=True,exist_ok=True); q.write_bytes(data)
   if sha(q)!=OUTPUT_EXPECTED[r]: fail('staged output hash mismatch: '+r)
   staged[r]=q
  replaced=[]
  try:
   for r in RELS: os.replace(staged[r],paths[r]); replaced.append(r)
  except Exception:
   for r in reversed(replaced): paths[r].write_bytes(backups[r])
   raise
  final={r:sha(paths[r]) for r in RELS}; bad=[r for r in RELS if final[r]!=OUTPUT_EXPECTED[r]]
  if bad:
   for r in RELS: paths[r].write_bytes(backups[r])
   fail('final output hash mismatch: '+', '.join(bad))
  m=json.loads(paths['manifest.json'].read_text('utf-8-sig'))
  if m.get('version')!=NEW_MANIFEST_VERSION or m.get('version_name')!=NEW_VERSION:
   for r in RELS: paths[r].write_bytes(backups[r])
   fail('final manifest version mismatch')
  print('APPLY_FIX331023_OK')
 finally:
  import shutil; shutil.rmtree(tmp,ignore_errors=True)
if __name__=='__main__':
 try: main()
 except Exception as e:
  print('APPLY_FIX331023_FAILED:',e,file=sys.stderr); sys.exit(1)
